const t0 = Date.now();

// ---------------------------------------------------------------------------
// Pass 1: the full triangle, for B, C, D.
// ---------------------------------------------------------------------------

const T1 = 3000;
const OFF = T1 + 1;
const W = 2 * T1 + 3;

