  for (const x of seedCells) P[0 * W + OFF + x] = 1;
  for (let t = 0; t + 1 < T; t++) {
    const a = t * W, b = (t + 1) * W;
    for (let i = 1; i <= W - 2; i++) P[b + i] = P[a + i - 1] ^ (P[a + i] | P[a + i + 1]);
